import { addDays } from 'date-fns'
import React, { useReducer, useRef } from 'react'
import Button from '../Button/Button'
import { useLocale } from '../contexts/LocaleContext'
import { Modes } from '../DatePicker/DatePicker'
import type { DayPickerInputProps } from './DatePickerInput'
import {
  DayPickerInput,
  RangePickerInput,
  WeekPickerInput,
} from './DatePickerInput'

const modes = {
  'Modes.Day': Modes.Day,
  'Modes.Week': Modes.Week,
  'Modes.Range': Modes.Range,
}

export default {
  title: 'Components/DatePickerInput',
  component: DayPickerInput,
  argTypes: {
    mode: {
      control: { type: 'select' },
      options: Object.keys(modes),
      mapping: modes,
    },
    initialDate: {
      control: 'date',
    },
    initialTimezone: {
      control: {
        type: 'select',
      },
      options: ['America/Regina', 'UTC', 'Asia/Tokyo'],
    },
  },
  args: {
    initialDate: new Date().toISOString().split('T')[0],
    label: 'Date',
    mode: Modes.Day,
  },
}

function Template(args: Omit<DayPickerInputProps, 'onChange'>): JSX.Element {
  const [error, toggleError] = useReducer((state) => !state, false)
  const clearRef = useRef<HTMLButtonElement | null>(null)
  const [, setLocale] = useLocale()

  const mode = args.mode as Modes

  const date = new Date((args.initialDate as unknown) as number)
  const initialDate = (mode === Modes.Range
    ? [date, addDays(date as Date, 10)]
    : date) as Date | [Date, Date]

  const Component = {
    [Modes.Day]: DayPickerInput,
    [Modes.Range]: RangePickerInput,
    [Modes.Week]: WeekPickerInput,
  }[mode]

  return (
    <div className="flex m-6 space-x-4">
      <Component
        {...args}
        clearRef={clearRef}
        error={error}
        helperText={error ? 'Date is invalid' : 'Select a date'}
        initialDate={initialDate}
        mode={mode}
      />
      <Button onClick={toggleError}>Validate date</Button>
      <Button onClick={() => clearRef.current?.click()}>Clear</Button>
      <div className="flex space-x-4">
        <Button onClick={() => setLocale('en')}>English</Button>
        <Button onClick={() => setLocale('fr')}>French</Button>
        <Button onClick={() => setLocale('es')}>Spanish</Button>
      </div>
    </div>
  )
}

export const Default = {
  render: Template,
}
